INSERT INTO cms_records ("id","kind","slug","draft","live","status","intent","version","updated_by","submitted_by","updated_at","mutation") VALUES ('jobs:qa-engineer','jobs','qa-engineer','{"aboutRole": "As a Software Developer, you will work with the engineering team to design, develop, test, and maintain web applications. You will collaborate with designers, QA engineers, and other developers to deliver high-quality software solutions. This role is suitable for candidates who enjoy problem-solving and learning new technologies.", "active": true, "applyEmail": "hr@ifranchise.in", "applyNote": "Send your CV and the role title.", "dept": "Tech", "experience": "1–4 Years", "id": "qa-engineer", "keySkills": ["Knowledge of React.js or another frontend framework.", "Basic understanding of REST APIs.", "Familiarity with Node.js or backend development.", "Experience with responsive web design.", "Knowledge of software testing and debugging.", "Familiarity with Agile development methodologies."], "location": "Bengaluru, Karnataka", "mode": "Onsite", "openings": "1", "reportsTo": "Product and Technology Team", "requirements": ["Bachelor''s degree in Computer Science, IT, or a related field, or equivalent practical skills.", "Basic knowledge of HTML, CSS, and JavaScript.", "Understanding of programming fundamentals and object-oriented concepts.", "Knowledge of databases and SQL.", "Familiarity with Git or other version control systems.", "Good analytical and problem-solving skills.", "Strong communication and teamwork abilities.", "Willingness to learn new technologies."], "responsibilities": ["Develop and maintain web applications.", "Write clean, reusable, and efficient code.", "Identify and fix software bugs and technical issues.", "Collaborate with designers, developers, and QA engineers.", "Participate in code reviews and team discussions.", "Test application functionality and improve performance.", "Maintain technical documentation.", "Learn and implement new technologies as required."], "salary": "₹3,00,000–₹5,00,000 per annum", "slug": "qa-engineer", "tagline": "We are looking for a passionate Software Developer to join our engineering team and help build reliable, scalable, and user-friendly web applications.", "title": "QA Engineer", "type": "Full-time", "whyJoin": "Work in a collaborative and supportive team environment.\nLearn from experienced developers and technical mentors.\nParticipate in real-world projects and solve practical challenges.\nReceive opportunities for professional development and skill enhancement.\nContribute ideas and take ownership of your work.\nBuild your career in a learning-focused workplace.", "workingHours": "10.00 Am to 7.00 Pm"}',NULL,'draft','publish',1,'migration@ifranchise.in',NULL,'2026-10-27T05:02:20.741Z','independent-export-2026-10-28');
INSERT INTO cms_records ("id","kind","slug","draft","live","status","intent","version","updated_by","submitted_by","updated_at","mutation") VALUES ('jobs:ui-ux-designer','jobs','ui-ux-designer','{"about": "We’re building a CRM and business application to support our teams and their everyday work. You’ll help turn complex workflows into useful product experiences.", "aboutRole": "We are looking for a highly skilled, product-focused UI/UX Designer who can turn complex business requirements into intuitive, scalable, and developer-ready product experiences. This is not a visual design-only role—we are looking for someone who understands user flows, product logic, enterprise workflows, and design systems.", "active": true, "applyEmail": "hr@ifranchise.in", "applyNote": "Submit your resume and portfolio demonstrating product design work, complex user flows, dashboards, design systems, and responsive applications.", "dept": "Design", "experience": "1–4 Years", "icon": {"children": {"d": "M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z", "strokeLinecap": "round", "strokeLinejoin": "round", "tag": "path"}, "className": "w-7 h-7", "fill": "none", "stroke": "currentColor", "strokeWidth": 1.8, "tag": "svg", "viewBox": "0 0 24 24"}, "id": "ui-ux-designer", "keySkills": ["1–4 years of relevant UI/UX or product design experience", "Advanced Figma skills", "Strong understanding of UX, user flows, and information architecture", "Strong visual hierarchy, typography, spacing, and interaction design skills", "Experience designing dashboards and data-heavy interfaces", "Experience with responsive and component-based design", "Strong understanding of design systems and reusable components", "Strong problem-solving and product-thinking ability", "Basic understanding of HTML/CSS and modern web interfaces", "Ability to work independently and deliver high-quality designs within deadlines"], "location": "Bengaluru, Karnataka", "mode": "Onsite", "opportunityPrompts": ["Can you turn complex business requirements into intuitive product experiences?", "Do you enjoy solving enterprise workflows and data-heavy UX problems?", "Can you create structured, developer-ready Figma files and scalable design systems?"], "reportsTo": "Product and Technology Team", "requirements": ["Experience designing CRM, ERP, HRMS, B2B SaaS, or enterprise applications (preferred)", "Experience with complex workflows and role-based interfaces (preferred)", "Portfolio demonstrating real product design work, complex user flows, dashboards, design systems, and responsive applications (preferred)", "Experience working directly with developers and providing production-ready design handoff (preferred)"], "responsibilities": ["Translate PRDs and business requirements into clear user flows and product experiences", "Design enterprise SaaS/CRM interfaces including dashboards, tables, forms, workflows, and data-heavy screens", "Create wireframes, prototypes, and high-fidelity UI designs using Figma", "Build and maintain reusable design systems and component libraries", "Design responsive experiences across desktop, tablet, and mobile", "Define complete UI states including loading, empty, error, success, validation, hover, active, and disabled states", "Work closely with developers, QA, and business stakeholders to ensure accurate implementation", "Maintain clean, structured, developer-ready Figma files with proper components, Auto Layout, variants, and specifications", "Review implemented designs and continuously improve the product experience based on feedback and testing"], "slug": "ui-ux-designer", "tagline": "Design intuitive, scalable, and developer-ready experiences for enterprise CRM and business applications.", "title": "UI/UX Designer", "type": "Full-time", "whyJoin": "Work on a real enterprise CRM and business application from the ground up. Solve complex product and UX problems, build scalable design systems, collaborate directly with technology and business teams, and create products used in real-world business operations."}',NULL,'archived','archive',6,'migration@ifranchise.in',NULL,'2026-10-27T08:08:16.088Z','independent-export-2026-10-28');
